// High-DPI PNG export
async function exportToPNG(
  element: HTMLElement,
  dpi = 300
): Promise<Blob> {
  const scale = dpi / 96
  const canvas = await html2canvas(element, {
    scale,
    backgroundColor: '#ffffff',
    useCORS: true,
  })
  return canvas.toBlob()
}

// PDF generation
async function exportToPDF(
  element: HTMLElement,
  layout: QRCardLayout,
  colorSpace: 'RGB' | 'CMYK' = 'RGB'
): Promise<Blob> {
  const dimensions = QR_CARD_SIZES[layout]
  const pdf = new jsPDF({
    unit: dimensions.unit,
    format: [dimensions.width, dimensions.height],
    compress: true,
  })

  const canvas = await html2canvas(element, { scale: 3.125 })
  const imgData = canvas.toDataURL('image/png')

  pdf.addImage(
    imgData,
    'PNG',
    0,
    0,
    dimensions.width,
    dimensions.height
  )

  return pdf.output('blob')
}

// Batch export as ZIP
async function batchExportPNG(
  venues: Venue[],
  config: QRCardConfig
): Promise<Blob> {
  const zip = new JSZip()

  for (const venue of venues) {
    const element = renderVenueCard(venue, config)
    const blob = await exportToPNG(element)
    zip.file(`${venue.slug}.png`, blob)
  }

  return zip.generateAsync({ type: 'blob' })
}

