async function saveQRConfig(venueId: number, config: QRCardConfig) {
  await fetch(`/api/venues/${venueId}/qr-config`, {
    method: 'POST',
    body: JSON.stringify(config)
  })

  // Or direct Prisma call
  await prisma.venue.update({
    where: { id: venueId },
    data: {
      qrCodeGenerated: true,
      qrCardStyle: config,
      updatedAt: new Date()
    }
  })
}

